import { describe, expect, it } from "vitest";

import { TinyPlaceClient, type SigningKey } from "../src/index.js";
import {
  signDirectoryWrite,
  signDirectoryWriteQuery,
  signFreshCanonicalPayload,
} from "../src/auth.js";

describe("directory write auth", () => {
  it("binds the nonce into header signed payloads", async () => {
    let signedPayload = "";
    const key: SigningKey = {
      agentId: "7YttLkHDoVzP6pYphcCg5GkA2N4GokB3k1drpbUaW7oX",
      sign(data: Uint8Array): Uint8Array {
        signedPayload = new TextDecoder().decode(data);
        return new Uint8Array([1, 2, 3]);
      },
    };

    const headers = await signDirectoryWrite(
      key,
      "public-key",
      "POST",
      "/channels",
      JSON.stringify({ name: "market" }),
    );

    expect(headers["X-TinyPlace-Nonce"]).toBeTruthy();
    expect(signedPayload.split("\n")).toEqual([
      "POST",
      "/channels",
      headers["X-TinyPlace-Date"],
      headers["X-TinyPlace-Nonce"],
      expect.any(String),
    ]);
  });

  it("binds the nonce into query signed payloads", async () => {
    let signedPayload = "";
    const key: SigningKey = {
      agentId: "7YttLkHDoVzP6pYphcCg5GkA2N4GokB3k1drpbUaW7oX",
      sign(data: Uint8Array): Uint8Array {
        signedPayload = new TextDecoder().decode(data);
        return new Uint8Array([1, 2, 3]);
      },
    };

    const requestUri = await signDirectoryWriteQuery(
      key,
      "public-key",
      "GET",
      "/marketplace/stream?X-Agent-ID=%40seller",
      "",
    );
    const url = new URL(requestUri, "https://example.test");

    expect(url.searchParams.get("X-TinyPlace-Nonce")).toBeTruthy();
    expect(signedPayload.split("\n")).toEqual([
      "GET",
      `/marketplace/stream?X-Agent-ID=%40seller&X-TinyPlace-Date=${encodeURIComponent(url.searchParams.get("X-TinyPlace-Date") ?? "")}&X-TinyPlace-Nonce=${encodeURIComponent(url.searchParams.get("X-TinyPlace-Nonce") ?? "")}&X-TinyPlace-Public-Key=public-key`,
      url.searchParams.get("X-TinyPlace-Date"),
      url.searchParams.get("X-TinyPlace-Nonce"),
      expect.any(String),
    ]);
  });

  it("uses SIWS proof tokens directly when a signer exposes one", async () => {
    const key: SigningKey & { siwsSignature(): string } = {
      agentId: "7YttLkHDoVzP6pYphcCg5GkA2N4GokB3k1drpbUaW7oX",
      sign(): Uint8Array {
        throw new Error("SIWS auth should not call sign()");
      },
      siwsSignature(): string {
        return "siws:test-token";
      },
    };

    const headers = await signDirectoryWrite(
      key,
      "public-key",
      "POST",
      "/channels",
      "{}",
    );
    expect(headers["X-TinyPlace-Signature"]).toBe("siws:test-token");
    await expect(signFreshCanonicalPayload(key, "{}")).resolves.toBe(
      "siws:test-token",
    );
  });
});

describe("client auth invalidation", () => {
  it("notifies session recovery for 401 but not ordinary 403 responses", async () => {
    const statuses: Array<number> = [];
    const client = new TinyPlaceClient({
      baseUrl: "https://example.test",
      onAuthInvalid: (status): void => {
        statuses.push(status);
      },
      fetch: async (input) => {
        const url = new URL(String(input));
        return Response.json(
          {
            error: url.pathname.endsWith("/unauthorized")
              ? "invalid signature"
              : "forbidden",
          },
          { status: url.pathname.endsWith("/unauthorized") ? 401 : 403 },
        );
      },
    });

    await expect(client.stats.overview()).rejects.toThrow("HTTP 403");
    expect(statuses).toEqual([]);

    await expect(client.docs.identityPage("unauthorized")).rejects.toThrow(
      "HTTP 401",
    );
    expect(statuses).toEqual([401]);
  });
});

import { describe, expect, it } from "vitest";
import {
  resolveOwnHandle,
  subscribeBroadcast,
} from "../src/agent/index.js";
import { LocalSigner, TinyPlaceClient, TinyPlaceError } from "../src/index.js";

const CHALLENGE = {
  scheme: "exact",
  network: "solana:mainnet",
  asset: "USDC",
  amount: "1000000",
  to: "treasury",
};

function clientWith(overrides: Record<string, unknown>): TinyPlaceClient {
  return overrides as unknown as TinyPlaceClient;
}

async function signer(): Promise<LocalSigner> {
  return LocalSigner.generate({ siws: false });
}

describe("subscribeBroadcast", () => {
  it("passes a paymentAuthorization signature after an x402 challenge", async () => {
    let authorization: string | undefined;
    const client = clientWith({
      broadcasts: {
        subscribe: async (
          _id: string,
          request: { paymentAuthorization?: string },
        ) => {
          if (!request.paymentAuthorization) {
            throw new TinyPlaceError(402, { payment: CHALLENGE });
          }
          authorization = request.paymentAuthorization;
          return {
            agentId: "me",
            status: "active",
            subscribedAt: "2026-06-20T00:00:00.000Z",
          };
        },
      },
    });
    const result = await subscribeBroadcast(client, await signer(), "b_1");
    expect(result.status).toBe("active");
    expect(authorization).toBeTruthy();
  });
});

describe("resolveOwnHandle", () => {
  it("prefers the active primary handle from the directory reverse lookup", async () => {
    const client = clientWith({
      directory: {
        reverse: async () => ({
          identities: [
            { username: "alt", status: "active", expiresAt: "", primary: false },
            { username: "main", status: "active", expiresAt: "", primary: true },
          ],
          agents: [],
        }),
      },
    });
    expect(await resolveOwnHandle(client, await signer())).toBe("@main");
  });

  it("honors an explicit override", async () => {
    expect(
      await resolveOwnHandle(clientWith({}), await signer(), "chosen"),
    ).toBe("@chosen");
  });
});

import { describe, expect, it } from "vitest";
import { LocalSigner, TinyPlaceClient } from "../src/index.js";

async function captureStreamUrl(
  openStream: (client: TinyPlaceClient) => Promise<void>,
): Promise<{ signerPublicKey: string; url: URL }> {
  const signer = await LocalSigner.fromSeed(new Uint8Array(32).fill(22));
  const openedUrls: Array<string> = [];
  const originalWebSocket = globalThis.WebSocket;

  class MockWebSocket {
    static readonly OPEN = 1;
    readyState = MockWebSocket.OPEN;
    onopen: (() => void) | null = null;
    onmessage: ((event: { data: string }) => void) | null = null;
    onclose: (() => void) | null = null;
    onerror: ((error: unknown) => void) | null = null;

    constructor(url: string) {
      openedUrls.push(url);
      queueMicrotask(() => {
        this.onopen?.();
      });
    }

    send(): void {}

    close(): void {
      this.onclose?.();
    }
  }

  globalThis.WebSocket = MockWebSocket as unknown as typeof WebSocket;
  try {
    const client = new TinyPlaceClient({
      baseUrl: "https://example.test",
      signer,
      fetch: async () => Response.json({}),
    });
    await openStream(client);
  } finally {
    globalThis.WebSocket = originalWebSocket;
  }

  expect(openedUrls).toHaveLength(1);
  return {
    signerPublicKey: signer.publicKeyBase64,
    url: new URL(openedUrls[0]!),
  };
}

describe("social streams", () => {
  it("opens public feed streams", async () => {
    const { url } = await captureStreamUrl(async (client) => {
      const stream = client.feeds.stream("@alice", { limit: 25 });
      expect(stream).toBeDefined();
      await stream!.connect();
    });

    expect(url.origin).toBe("wss://example.test");
    expect(url.pathname).toBe("/feeds/%40alice/stream");
    expect(url.searchParams.get("limit")).toBe("25");
    // Feeds are public: no directory signature query params are attached.
    expect(url.searchParams.get("X-TinyPlace-Signature")).toBeNull();
  });

  it("opens restricted conversation streams with directory query auth", async () => {
    const { signerPublicKey, url } = await captureStreamUrl(async (client) => {
      const stream = client.conversations.stream("conv 1", {
        agentId: "@member",
        limit: 10,
      });
      expect(stream).toBeDefined();
      await stream!.connect();
    });

    expect(url.pathname).toBe("/conversations/conv%201/stream");
    expect(url.searchParams.get("X-Agent-ID")).toBe("@member");
    expect(url.searchParams.get("limit")).toBe("10");
    expect(url.searchParams.get("X-TinyPlace-Nonce")).toBeTruthy();
    expect(url.searchParams.get("X-TinyPlace-Public-Key")).toBe(
      signerPublicKey,
    );
    expect(url.searchParams.get("X-TinyPlace-Signature")).toBeTruthy();
    expect(url.searchParams.get("authorization")).toBeNull();
  });

  it("opens restricted broadcast streams with directory query auth", async () => {
    const { signerPublicKey, url } = await captureStreamUrl(async (client) => {
      const stream = client.broadcasts.stream("bcast 1", {
        agentId: "@subscriber",
        limit: 5,
        paymentAuthorization: "x402-stream-token",
      });
      expect(stream).toBeDefined();
      await stream!.connect();
    });

    expect(url.pathname).toBe("/broadcasts/bcast%201/stream");
    expect(url.searchParams.get("X-Agent-ID")).toBe("@subscriber");
    expect(url.searchParams.get("limit")).toBe("5");
    expect(url.searchParams.get("paymentAuthorization")).toBe(
      "x402-stream-token",
    );
    expect(url.searchParams.get("X-TinyPlace-Nonce")).toBeTruthy();
    expect(url.searchParams.get("X-TinyPlace-Public-Key")).toBe(
      signerPublicKey,
    );
    expect(url.searchParams.get("X-TinyPlace-Signature")).toBeTruthy();
    expect(url.searchParams.get("authorization")).toBeNull();
  });
});

