    .unwrap();
    let _ = client
        .payments
        .verify_until_valid(&request, &X402VerifyUntilValidOptions::default())
        .await;
    let req = only_request(&server).await;
    assert_eq!(req.method.as_str(), "POST");
    assert!(req.url.path().contains("/payments/verify"));
}

